-- key: creature_id
SELECT "creature_id", "patch", "RewOnKillRepFaction1", "RewOnKillRepFaction2", "MaxStanding1", "IsTeamAward1", "RewOnKillRepValue1", "MaxStanding2", "IsTeamAward2", "RewOnKillRepValue2", "TeamDependent" FROM (SELECT "creature_id", "patch", "RewOnKillRepFaction1", "RewOnKillRepFaction2", "MaxStanding1", "IsTeamAward1", "RewOnKillRepValue1", "MaxStanding2", "IsTeamAward2", "RewOnKillRepValue2", "TeamDependent", ROW_NUMBER() OVER (PARTITION BY "creature_id" ORDER BY "patch" DESC, rowid DESC) AS __rn FROM "creature_onkill_reputation" WHERE "patch" <= 10) WHERE __rn = 1
